     1  package io.github.hectorvent.floci.core.storage;
     2  
     3  import io.github.hectorvent.floci.config.EmulatorConfig;
     4  import io.github.hectorvent.floci.core.common.RequestContext;
     5  import io.github.hectorvent.floci.core.common.ServiceConfigAccess;
     6  import com.fasterxml.jackson.core.type.TypeReference;
     7  import jakarta.enterprise.context.ApplicationScoped;
     8  import jakarta.enterprise.inject.Instance;
     9  import jakarta.inject.Inject;
    10  import org.jboss.logging.Logger;
    11  
    12  import java.nio.file.Path;
    13  import java.util.ArrayList;
    14  import java.util.List;
    15  import java.util.Map;
    16  
    17  /**
    18   * Factory that creates {@link AccountAwareStorageBackend} instances based on configuration.
    19   * Every backend is wrapped in an account-aware decorator so resources are automatically
    20   * namespaced by the account ID of the calling credential.
    21   * Tracks all created backends for lifecycle management.
    22   */
    23  @ApplicationScoped
    24  public class StorageFactory {
    25  
    26      private static final Logger LOG = Logger.getLogger(StorageFactory.class);
    27  
    28      private final EmulatorConfig config;
    29      private final ServiceConfigAccess serviceConfigAccess;
    30      private final List<StorageBackend<?, ?>> allBackends = new ArrayList<>();
    31      private final List<HybridStorage<?, ?>> hybridBackends = new ArrayList<>();
    32      private final List<WalStorage<?, ?>> walBackends = new ArrayList<>();
    33  
    34      @Inject
    35      Instance<RequestContext> requestContextInstance;
    36  
    37      @Inject
    38      public StorageFactory(EmulatorConfig config, ServiceConfigAccess serviceConfigAccess) {
    39          this.config = config;
    40          this.serviceConfigAccess = serviceConfigAccess;
    41      }
    42  
    43      /**
    44       * Create an account-aware storage backend for the given service.
    45       * All keys are automatically prefixed with the current account ID derived from
    46       * the request credential. Async workers should use the {@code *ForAccount} overloads
    47       * on {@link AccountAwareStorageBackend} with the account ID stored on the resource model.
    48       *
    49       * @param serviceName   the service name (ssm, sqs, s3, …)
    50       * @param fileName      the JSON file name for persistent storage
    51       * @param typeReference Jackson type reference for deserialization
    52       */
    53      public <V> StorageBackend<String, V> create(String serviceName, String fileName,
    54                                                   TypeReference<Map<String, V>> typeReference) {
    55          String mode = resolveMode(serviceName);
    56          long flushInterval = resolveFlushInterval(serviceName);
    57          Path basePath = Path.of(config.storage().persistentPath());
    58          Path filePath = basePath.resolve(fileName);
    59  
    60          LOG.debugv("Creating {0} storage for service {1} (file: {2})", mode, serviceName, filePath);
    61  
    62          StorageBackend<String, V> inner = switch (mode) {
    63              case "memory" -> new InMemoryStorage<>();
    64              case "persistent" -> new PersistentStorage<>(filePath, typeReference);
    65              case "hybrid" -> {
    66                  var hybrid = new HybridStorage<>(filePath, typeReference, flushInterval);
    67                  hybridBackends.add(hybrid);
    68                  yield hybrid;
    69              }
    70              case "wal" -> {
    71                  Path snapshotPath = basePath.resolve(fileName.replace(".json", "-snapshot.json"));
    72                  Path walFilePath = basePath.resolve(fileName.replace(".json", ".wal"));
    73                  long compactionInterval = config.storage().wal().compactionIntervalMs();
    74                  var wal = new WalStorage<>(snapshotPath, walFilePath, typeReference, compactionInterval);
    75                  walBackends.add(wal);
    76                  yield wal;
    77              }
    78              default -> throw new IllegalArgumentException("Unknown storage mode: " + mode);
    79          };
    80  
    81          inner.load();
    82  
    83          AccountAwareStorageBackend<V> backend = new AccountAwareStorageBackend<>(
    84                  inner, requestContextInstance, config.defaultAccountId());
    85          allBackends.add(backend);
    86          return backend;
    87      }
    88  
    89      /** Load all storage backends from disk. */
    90      public void loadAll() {
    91          for (StorageBackend<?, ?> backend : allBackends) {
    92              backend.load();
    93          }
    94      }
    95  
    96      /** Flush all storage backends to disk. */
    97      public void flushAll() {
    98          for (StorageBackend<?, ?> backend : allBackends) {
    99              backend.flush();
   100          }
   101      }
   102  
   103      /** Clear all storage backends. */
   104      public void clearAll() {
   105          for (StorageBackend<?, ?> backend : allBackends) {
   106              backend.clear();
   107          }
   108          flushAll();
   109      }
   110  
   111      /** Shutdown all managed backends (stop schedulers, close connections). */
   112      public void shutdownAll() {
   113          for (HybridStorage<?, ?> hybrid : hybridBackends) {
   114              hybrid.shutdown();
   115          }
   116          for (WalStorage<?, ?> wal : walBackends) {
   117              wal.shutdown();
   118          }
   119          flushAll();
   120      }
   121  
   122      private String resolveMode(String serviceName) {
   123          return serviceConfigAccess.storageMode(serviceName);
   124      }
   125  
   126      private long resolveFlushInterval(String serviceName) {
   127          return serviceConfigAccess.storageFlushInterval(serviceName);
   128      }
   129  }
